# Von Hand ergänzt (#129): Der Zeitraum einer Ausleihe ändert sich nur durch eine Verlängerung.
# Erlaubt ist allein ein späteres Ende einer laufenden Ausleihe, und nur, wenn der passende
# Eintrag in lending_loanextension schon angehängt ist; alles andere bleibt wie in 0001.
GUARD = """
    CREATE OR REPLACE FUNCTION lending_loan_guard() RETURNS trigger
    LANGUAGE plpgsql AS $$
    BEGIN
        IF TG_OP = 'DELETE' THEN
            RAISE EXCEPTION 'Ausleihe %: Ausleihen werden nicht gelöscht.', OLD.id
                USING ERRCODE = 'restrict_violation';
        END IF;
        IF (NEW.id, NEW.booking_id, NEW.part_id, NEW.created_at)
            IS DISTINCT FROM
           (OLD.id, OLD.booking_id, OLD.part_id, OLD.created_at) THEN
            RAISE EXCEPTION 'Ausleihe %: nur der Status darf sich ändern.', OLD.id
                USING ERRCODE = 'restrict_violation';
        END IF;
        IF NEW.period IS DISTINCT FROM OLD.period THEN
            IF lower(NEW.period) IS DISTINCT FROM lower(OLD.period)
               OR upper(NEW.period) <= upper(OLD.period)
               OR OLD.status <> 'lent' OR NEW.status <> 'lent'
               OR NOT EXISTS (
                   SELECT 1 FROM lending_loanextension AS extension
                   WHERE extension.loan_id = OLD.id
                     AND extension.old_end = upper(OLD.period) - 1
                     AND extension.new_end = upper(NEW.period) - 1
               ) THEN
                RAISE EXCEPTION 'Ausleihe %: Der Zeitraum ändert sich nur durch eine Verlängerung.',
                    OLD.id USING ERRCODE = 'restrict_violation';
            END IF;
        END IF;
        IF NOT (
            NEW.status = OLD.status
            OR (OLD.status = 'reserved' AND NEW.status IN ('lent', 'cancelled'))
            OR (OLD.status = 'lent' AND NEW.status = 'returned')
        ) THEN
            RAISE EXCEPTION 'Ausleihe %: Statuswechsel % -> % ist nicht erlaubt.',
                OLD.id, OLD.status, NEW.status
                USING ERRCODE = 'restrict_violation';
        END IF;
        RETURN NEW;
    END;
    $$;
"""

